import{_ as r,o as n,c as o,j as e,a,aj as i}from"./chunks/framework.C6uXqnaX.js";const f=JSON.parse('{"title":"Expression Changed After Checked","description":"","frontmatter":{},"headers":[],"relativePath":"en/errors/NG0100.md","filePath":"en/errors/NG0100.md"}'),s={name:"en/errors/NG0100.md"};function h(c,t,d,l,u,g){return n(),o("div",null,t[0]||(t[0]=[e("h1",{id:"expression-changed-after-checked",tabindex:"-1"},[a("Expression Changed After Checked "),e("a",{class:"header-anchor",href:"#expression-changed-after-checked","aria-label":'Permalink to "Expression Changed After Checked"'},"​")],-1),e("iframe",{src:"https://www.youtube.com/embed/O47uUnJjbJc",title:"Video",style:{width:"100%","aspect-ratio":"16/9",border:"0"},allowfullscreen:""},null,-1),i('<p>Angular throws an <code>ExpressionChangedAfterItHasBeenCheckedError</code> when an expression value has been changed after change detection has completed. Angular only throws this error in development mode.</p><p>In development mode, Angular performs an additional check after each change detection run, to ensure the bindings haven&#39;t changed. This catches errors where the view is left in an inconsistent state. This can occur, for example, if a method or getter returns a different value each time it is called, or if a child component changes values on its parent. If either of these occurs, this is a sign that change detection is not stabilized. Angular throws the error to ensure data is always reflected correctly in the view, which prevents erratic UI behavior or a possible infinite loop.</p><p>This error commonly occurs when you&#39;ve added template expressions or have begun to implement lifecycle hooks like <code>ngAfterViewInit</code> or <code>ngOnChanges</code>. It is also common when dealing with loading status and asynchronous operations, or when a child component changes its parent bindings.</p><h2 id="debugging-the-error" tabindex="-1">Debugging the error <a class="header-anchor" href="#debugging-the-error" aria-label="Permalink to &quot;Debugging the error&quot;">​</a></h2><p>The <a href="https://developer.mozilla.org/docs/Tools/Debugger/How_to/Use_a_source_map" target="_blank" rel="noreferrer">source maps</a> generated by the CLI are very useful when debugging. Navigate up the call stack until you find a template expression where the value displayed in the error has changed.</p><p>Ensure that there are no changes to the bindings in the template after change detection is run. This often means refactoring to use the correct component lifecycle hook for your use case. If the issue exists within <code>ngAfterViewInit</code>, the recommended solution is to use a constructor or <code>ngOnInit</code> to set initial values, or use <code>ngAfterContentInit</code> for other value bindings.</p><p>If you are binding to methods in the view, ensure that the invocation does not update any of the other bindings in the template.</p><p>Read more about which solution is right for you in <a href="https://medium.com/angular-in-depth/everything-you-need-to-know-about-the-expressionchangedafterithasbeencheckederror-error-e3fd9ce7dbb4" target="_blank" rel="noreferrer">&#39;Everything you need to know about the &quot;ExpressionChangedAfterItHasBeenCheckedError&quot; error&#39;</a> and why this is useful at <a href="https://blog.angular-university.io/angular-debugging" target="_blank" rel="noreferrer">&#39;Angular Debugging &quot;Expression has changed after it was checked&quot;: Simple Explanation (and Fix)&#39;</a>.</p>',8)]))}const m=r(s,[["render",h]]);export{f as __pageData,m as default};
